+package handler
+
+import (
+	"errors"
+	"time"
+)
+
+// RetryPolicy decides whether a failed attempt should be tried again.
+type RetryPolicy interface {
+	// ShouldRetry reports whether the 1-based attempt that failed with err should
+	// be retried, and how long to wait before doing so.
+	ShouldRetry(attempt int, err error) (time.Duration, bool)
+}
+
+// NoRetry never retries.
+type NoRetry struct{}
+
+// ShouldRetry implements RetryPolicy.
+func (NoRetry) ShouldRetry(int, error) (time.Duration, bool) { return 0, false }
+
+// RetryOn retries up to Max extra times when err matches Sentinel, waiting
+// Delay between attempts.
+type RetryOn struct {
+	Sentinel error
+	Max      int
+	Delay    time.Duration
+}
+
+// ShouldRetry implements RetryPolicy.
+func (p RetryOn) ShouldRetry(attempt int, err error) (time.Duration, bool) {
+	if attempt > p.Max || !errors.Is(err, p.Sentinel) {
+		return 0, false
+	}
+	return p.Delay, true
+}
+
+// retry runs fn until it succeeds or policy declines another attempt.
+func retry(policy RetryPolicy, fn func() error) error {
+	for attempt := 1; ; attempt++ {
+		err := fn()
+		if err == nil {
+			return nil
+		}
+		delay, again := policy.ShouldRetry(attempt, err)
+		if !again {
+			return err
+		}
+		if delay > 0 {
+			time.Sleep(delay)
+		}
+	}
+}
